node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get full user profile for user_d3d5d0c8 (Maya Chen - state-customer-support/shopping)
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_d3d5d0c8'\").get();
console.log('=== USER PROFILE ===');
console.log(JSON.stringify(user, null, 2));

// Get all orders for this user
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = 'user_d3d5d0c8'\").all();
console.log('\n=== ALL ORDERS ===');
for (const o of orders) {
  console.log(JSON.stringify(o, null, 2));
}

// Get order items for the two specific orders
const items1 = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-5B048F'\").all();
console.log('\n=== ORD-5B048F ITEMS ===');
for (const i of items1) { console.log(JSON.stringify(i, null, 2)); }

const items2 = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-CCC96C'\").all();
console.log('\n=== ORD-CCC96C ITEMS ===');
for (const i of items2) { console.log(JSON.stringify(i, null, 2)); }

// Get payment methods from rt_payment_methods
const payments = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = 'user_d3d5d0c8'\").all();
console.log('\n=== PAYMENT METHODS (rt_payment_methods) ===');
for (const p of payments) { console.log(JSON.stringify(p, null, 2)); }

// Get order fulfillments
const ful1 = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-5B048F'\").all();
const ful2 = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-CCC96C'\").all();
console.log('\n=== FULFILLMENTS ORD-5B048F ===');
for (const f of ful1) { console.log(JSON.stringify(f, null, 2)); }
console.log('\n=== FULFILLMENTS ORD-CCC96C ===');
for (const f of ful2) { console.log(JSON.stringify(f, null, 2)); }

// Get order payments
const pay1 = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-5B048F'\").all();
const pay2 = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-CCC96C'\").all();
console.log('\n=== PAYMENTS ORD-5B048F ===');
for (const p of pay1) { console.log(JSON.stringify(p, null, 2)); }
console.log('\n=== PAYMENTS ORD-CCC96C ===');
for (const p of pay2) { console.log(JSON.stringify(p, null, 2)); }
